"use client";

import { useRouter } from "next/navigation";
import { LogOut } from "lucide-react";
import ChannelSwitcher from "./ChannelSwitcher";

type User = {
  displayName: string;
  twitchLogin: string;
  profileImageUrl: string;
  isDev: boolean;
  isStreamer: boolean;
};

export default function TopBar({ user }: { user: User | null }) {
  const router = useRouter();

  const handleLogout = async () => {
    await fetch("/dashboard/api/auth/logout", { method: "POST" });
    router.push("/login");
  };

  return (
    <header className="h-14 bg-card border-b border-line flex items-center justify-between px-6 shrink-0">
      <div className="flex items-center">
        <ChannelSwitcher />
      </div>

      {user && (
        <div className="flex items-center gap-3">
          {user.isDev && (
            <span
              className="text-[10px] font-bold uppercase tracking-widest px-2 py-1 rounded-md"
              style={{
                color: "var(--color-brand-muted)",
                background: "color-mix(in srgb, var(--color-brand) 12%, transparent)",
                border: "1px solid color-mix(in srgb, var(--color-brand) 25%, transparent)",
              }}
            >
              Dev
            </span>
          )}
          {user.isStreamer && !user.isDev && (
            <span
              className="text-[10px] font-bold uppercase tracking-widest px-2 py-1 rounded-md"
              style={{
                color: "var(--color-success)",
                background: "color-mix(in srgb, var(--color-success) 10%, transparent)",
                border: "1px solid color-mix(in srgb, var(--color-success) 20%, transparent)",
              }}
            >
              Streamer
            </span>
          )}

          <div className="flex items-center gap-2.5">
            {user.profileImageUrl && (
              <img
                src={user.profileImageUrl}
                alt={user.displayName}
                width={28}
                height={28}
                className="rounded-full border border-line shrink-0"
              />
            )}
            <div className="leading-none">
              <div className="text-fg text-[13px] font-semibold">{user.displayName}</div>
              <div className="text-fg-subtle text-[11px] mt-0.5">@{user.twitchLogin}</div>
            </div>
          </div>

          <button onClick={handleLogout} className="btn-ghost ml-1">
            <LogOut size={13} />
            Sign out
          </button>
        </div>
      )}
    </header>
  );
}
